  const edgarSearch = (term, cik) => `https://www.sec.gov/edgar/search/#/q=${encodeURIComponent('"' + term + '"')}${cik ? '&ciks=' + String(cik).padStart(10, '0') : ''}`;

  // This company's own example, from the record saved with the imported value
  function companyExample(key, model) {
    const s = model && model.sources && model.sources[key];
    const co = model && model.inputs && model.inputs.company && model.inputs.company.name;
    if (!s || !s.accn) return null;
    const raw = isNum(s.raw) ? s.raw.toLocaleString('en-US') + (s.rawUnit ? ' ' + s.rawUnit : '') : null;
    const v = key.startsWith('hist.') ? null : model.inputs[key];
    return { kind: 'company', text: `${co || 'This company'} ${s.form}${s.period ? ', ' + s.period : ''} (accession ${s.accn}${s.filed ? ', filed ' + s.filed : ''})${raw ? ': reported ' + raw : ''}${isNum(v) ? ' → ' + v.toLocaleString('en-US', { maximumFractionDigits: 6 }) + ' ' + (s.unit || '') : ''}.${s.concept ? ' SEC tag ' + s.concept + '.' : ''}`, url: s.url, cite: s.form + ' ' + s.accn };
  }
  function example(key, model) {
    const c = companyExample(key, model);
    const h = H[key];
    const v = h && h.example ? h.example() : null;
    return { company: c, verified: v };
  }
